static const float2 center = float2 (0,10+q24);
static const float  spec[16] = {frac(_qa),frac(_qb),frac(_qc),frac(_qd)};
static const float  maxh[16] = {floor(_qa),floor(_qb),floor(_qc),floor(_qd)};

float2 noise3 (float2 uvi) {float tmp; float2 fu = pow(mod.y,1.5)*abs(pow(frac (uvi)-0.5,mod.y)); 
  tmp=(0.87-mod.x*length(fu));
  return float2 (sat(1-abs(tmp))  +sat(.25-8*abs(fu.x-0.5)), tmp);}

float3 rs_lav (float2 uvi, float berg) {float z; float2 rs; float a = q21;
  uvi.y += (uvi.x)*q23;
  z = 1.0/(uvi.y+hory)*(4+q22-berg*.23); z = clamp (z,-0,30);   rs = float2 (uvi.x,1)* z; 
  return float3(mul (rs-center, float2x2 (cos(a), sin(a), -sin(a), cos(a)))+center,z); }

